let tamagotchiLifeMinutes = 0; // Real-time life clock (classic Tamagotchi pacing)
let tamagotchiEggGeneration = 0; // Bumps on intentional egg reset; blocks stale tabs from wiping progress
let tamagotchiTickIntervalId = null;
let tamagotchiOfficeHoursReloadTimerId = null;
let tamagotchiDataLoaded = false; // Gate ticks until storage is loaded (prevents egg/none clobber)
let mascotStagePreviewLock = false;
let mascotStagePreviewStage = null;
let mascotStagePreviewTimeout = null;

// Life only advances during office hours (09:00–21:00). Outside that window the
// mascot is frozen so leaving the PC on overnight won't age or starve it.
const TAMA_OFFICE_HOUR_START = 9;  // inclusive
const TAMA_OFFICE_HOUR_END = 21;   // exclusive (stops at 21:00)
const TAMA_OFFICE_HOURS_RELOAD_DELAY_MS = 5000;

// Stage thresholds in office-minutes. Baseline ≈7.5 office-days (12h/day) to final evo.
const TAMA_STAGE_MINUTES_BASE = {
    egg: 0,
    evo1: 1,          // 1 office-min — hatch
    evo2: 2700,       // ~3.8 office-days
    evo3: 5400,       // ~7.5 office-days — final evolution
    death: 36000,     // ~50 office-days
};
const TAMA_DEFAULT_DAYS_TO_FINAL = 7.5;
const TAMA_OFFICE_MINUTES_PER_DAY = (TAMA_OFFICE_HOUR_END - TAMA_OFFICE_HOUR_START) * 60; // 720
const TAMA_LIFESPAN_DAYS_KEY = 'tm_mascot_lifespan_days';

/** Live thresholds — mutated by debug lifespan scale (keep same object ref). */
const TAMA_STAGE_MINUTES = { ...TAMA_STAGE_MINUTES_BASE };

function getMascotLifespanDays() {
    try {
        if (typeof GM_getValue === 'function') {
            const raw = Number(GM_getValue(TAMA_LIFESPAN_DAYS_KEY, TAMA_DEFAULT_DAYS_TO_FINAL));
            if (Number.isFinite(raw) && raw > 0) {
                return Math.min(365, Math.max(0.05, raw));
            }
        }
    } catch (_) { /* ignore */ }
    return TAMA_DEFAULT_DAYS_TO_FINAL;
}

function setMascotLifespanDays(days) {
    const next = Number(days);
    const clamped = Number.isFinite(next) && next > 0
        ? Math.min(365, Math.max(0.05, next))
        : TAMA_DEFAULT_DAYS_TO_FINAL;
    try {
        if (typeof GM_setValue === 'function') {
            GM_setValue(TAMA_LIFESPAN_DAYS_KEY, clamped);
        }
    } catch (_) { /* ignore */ }
    refreshTamaLifespanScale();
    return clamped;
}

function refreshTamaLifespanScale() {
    const days = getMascotLifespanDays();
    const targetFinalMinutes = days * TAMA_OFFICE_MINUTES_PER_DAY;
    const scale = targetFinalMinutes / TAMA_STAGE_MINUTES_BASE.evo3;
    const order = ['evo1', 'evo2', 'evo3', 'death'];
    TAMA_STAGE_MINUTES.egg = 0;
    let prev = 0;
    order.forEach((key) => {
        const base = TAMA_STAGE_MINUTES_BASE[key];
        let value = key === 'evo1'
            ? Math.max(1, Math.round(base * Math.max(scale, 0.0001)))
            : Math.max(prev + 1, Math.round(base * scale));
        TAMA_STAGE_MINUTES[key] = value;
        prev = value;
    });
    return {
        days,
        scale,
        stages: { ...TAMA_STAGE_MINUTES },
    };
}

refreshTamaLifespanScale();

/** Minutes between two timestamps that fall inside office hours (09:00–21:00 local). */
function getOfficeMinutesBetween(startMs, endMs) {
    const start = Number(startMs);
    const end = Number(endMs);
    if (!Number.isFinite(start) || !Number.isFinite(end) || !(end > start)) return 0;
    let totalMs = 0;
    const day = new Date(start);
    day.setHours(0, 0, 0, 0);
    while (day.getTime() < end) {
        const officeStart = new Date(day);
        officeStart.setHours(TAMA_OFFICE_HOUR_START, 0, 0, 0);
        const officeEnd = new Date(day);
        officeEnd.setHours(TAMA_OFFICE_HOUR_END, 0, 0, 0);
        const segStart = Math.max(start, officeStart.getTime());
        const segEnd = Math.min(end, officeEnd.getTime());
        if (segEnd > segStart) totalMs += segEnd - segStart;
        day.setDate(day.getDate() + 1);
    }
    return totalMs / 60000;
}

/** True during office hours (09:00–21:00 local). Life/stats are frozen outside this window. */
function isTamagotchiOfficeHoursNow(atMs = Date.now()) {
    const hour = new Date(atMs).getHours();
    return hour >= TAMA_OFFICE_HOUR_START && hour < TAMA_OFFICE_HOUR_END;
}

/** Milliseconds until the next office-hours boundary (09:00 or 21:00 local). */
function getMsUntilNextOfficeHoursBoundary(atMs = Date.now()) {
    const now = new Date(atMs);
    const y = now.getFullYear();
    const mo = now.getMonth();
    const d = now.getDate();

    const todayStart = new Date(y, mo, d, TAMA_OFFICE_HOUR_START, 0, 0, 0);
    const todayEnd = new Date(y, mo, d, TAMA_OFFICE_HOUR_END, 0, 0, 0);

    if (atMs < todayStart.getTime()) {
        return todayStart.getTime() - atMs;
    }
    if (atMs < todayEnd.getTime()) {
        return todayEnd.getTime() - atMs;
    }
    const tomorrowStart = new Date(y, mo, d + 1, TAMA_OFFICE_HOUR_START, 0, 0, 0);
    return tomorrowStart.getTime() - atMs;
}

function scheduleTamagotchiOfficeHoursPageReload(STORAGE_KEYS) {
    if (tamagotchiOfficeHoursReloadTimerId) {
        clearTimeout(tamagotchiOfficeHoursReloadTimerId);
        tamagotchiOfficeHoursReloadTimerId = null;
    }

    const delay = getMsUntilNextOfficeHoursBoundary();
    if (!Number.isFinite(delay) || delay < 0) {
        tamagotchiOfficeHoursReloadTimerId = setTimeout(
            () => scheduleTamagotchiOfficeHoursPageReload(STORAGE_KEYS),
            60000
        );
        return;
    }

    tamagotchiOfficeHoursReloadTimerId = setTimeout(() => {
        const keys = STORAGE_KEYS || (typeof window.STORAGE_KEYS !== 'undefined' ? window.STORAGE_KEYS : null);
        if (keys) {
            flushTamagotchiLifeToStorage(keys);
        }
        setTimeout(() => {
            try {
                location.reload();
            } catch (_) {
                scheduleTamagotchiOfficeHoursPageReload(keys);
            }
        }, TAMA_OFFICE_HOURS_RELOAD_DELAY_MS);
    }, delay);
}

function installTamagotchiOfficeHoursReload(STORAGE_KEYS) {
    if (window.__tmOfficeHoursReloadBound) return;
    window.__tmOfficeHoursReloadBound = true;

    scheduleTamagotchiOfficeHoursPageReload(STORAGE_KEYS);

    document.addEventListener('visibilitychange', () => {
        if (document.visibilityState !== 'visible') return;
        const keys = typeof window.STORAGE_KEYS !== 'undefined' ? window.STORAGE_KEYS : STORAGE_KEYS;
        scheduleTamagotchiOfficeHoursPageReload(keys);
    });
}

const TAMA_CHARACTER_TYPES = ['dragon', 'robot', 'slime', 'plant', 'ghost', 'cat', 'phoenix', 'crystal', 'aether', 'leviathan'];
const TAMA_LEGENDARY_TYPES = ['dragon'];
const TAMA_MYTHICAL_TYPES = ['phoenix', 'aether', 'leviathan'];
/** Legendary + Mythical mascots — uniform size boost on all evolution forms. */
const TAMA_ELITE_MASCOT_TYPES = [...TAMA_LEGENDARY_TYPES, ...TAMA_MYTHICAL_TYPES];
const MASCOT_BASE_SIZE_PX = 100;
const MASCOT_ELITE_SIZE_MULT = 1.25;

function resolveMascotCharacterType(container, characterType = tamagotchiCharacterType) {
    if (characterType && characterType !== 'none' && TAMA_CHARACTER_TYPES.includes(characterType)) {
        return characterType;
    }
    if (!container) return characterType || 'none';
    const fromData = container.dataset?.tmChar;
    if (fromData && fromData !== 'none' && TAMA_CHARACTER_TYPES.includes(fromData)) {
        return fromData;
    }
    const fromContainerClass = [...container.classList].find((cls) => cls.startsWith('mascot-char-'));
    if (fromContainerClass) {
        const type = fromContainerClass.slice('mascot-char-'.length);
        if (TAMA_CHARACTER_TYPES.includes(type)) return type;
    }
    const robot = container.querySelector('.tm-mascot-robot');
    const fromRobotClass = robot
        ? [...robot.classList].find((cls) => cls.startsWith('mascot-char-'))
        : null;
    if (fromRobotClass) {
        const type = fromRobotClass.slice('mascot-char-'.length);
        if (TAMA_CHARACTER_TYPES.includes(type)) return type;
    }
    return characterType || 'none';
}

/** Stage growth for mythics — applied on flipper so idle/eat animations don't wipe it. */
const TAMA_STAGE_VISUAL_SCALE = {
    phoenix: { evo1: 1, evo2: 1.22, evo3: 1.32 },
    leviathan: { evo1: 1, evo2: 1.24, evo3: 1.34 },
    aether: { evo1: 1, evo2: 1.07, evo3: 1.14 },
};

function getMascotStageVisualScale(stage = tamagotchiStage, characterType = tamagotchiCharacterType) {
    const resolved = TAMA_CHARACTER_TYPES.includes(characterType) ? characterType : 'none';
    const table = TAMA_STAGE_VISUAL_SCALE[resolved];
    const scale = Number(table?.[stage]);
    return Number.isFinite(scale) && scale > 0 ? scale : 1;
}

function syncMascotStageVisualScale(
    container = document.getElementById('tm-mascot-container'),
    stage = tamagotchiStage,
    characterType = tamagotchiCharacterType,
) {
    if (!container) return;
    const resolved = resolveMascotCharacterType(container, characterType);
    const scale = getMascotStageVisualScale(stage, resolved);
    container.style.setProperty('--tm-stage-scale', String(scale));
    container.dataset.tmStageScale = String(scale);
}

function syncEliteMascotContainerSize(
    container = document.getElementById('tm-mascot-container'),
    characterType = tamagotchiCharacterType,
) {
    if (!container) return;
    const resolved = resolveMascotCharacterType(container, characterType);
    const isElite = TAMA_ELITE_MASCOT_TYPES.includes(resolved);
    const stage = getEffectiveMascotStage();
    const stageScale = getMascotStageVisualScale(stage, resolved);
    // Elite base + stage growth as real px — stable vs animation transform fights
    const sizePx = Math.round(
        MASCOT_BASE_SIZE_PX * (isElite ? MASCOT_ELITE_SIZE_MULT : 1) * stageScale
    );
    container.style.width = `${sizePx}px`;
    container.style.height = `${sizePx}px`;
    container.classList.toggle('tm-mascot-elite-size', isElite);
    if (resolved && resolved !== 'none' && TAMA_CHARACTER_TYPES.includes(resolved)) {
        TAMA_CHARACTER_TYPES.forEach((t) => container.classList.remove(`mascot-char-${t}`));
        container.classList.add(`mascot-char-${resolved}`);
    }
    syncMascotStageVisualScale(container, stage, resolved);
}

