/**
 * Lore for a named evolution form. Locked stages return null (no spoilers).
 * @param {string|null} characterType
 * @param {string} stage
 * @param {{ locked?: boolean, revealLocked?: boolean }} [opts]
 */
function getMascotEvolutionLore(characterType, stage, opts = {}) {
    if (!stage || stage === 'egg') return null;
    const locked = opts.locked != null
        ? !!opts.locked
        : !isMascotStageUnlockedForPreview(stage, characterType || 'none');
    if (locked && !opts.revealLocked) return null;
    if (!characterType || characterType === 'none') return null;
    return MASCOT_EVOLUTION_LORE[characterType]?.[stage] || null;
}

function getNextMascotLifeStage(stage = tamagotchiStage) {
    const idx = getMascotLifeStageIndex(stage);
    if (idx < 0 || idx >= TAMA_LIFE_STAGE_ORDER.length - 1) return null;
    return TAMA_LIFE_STAGE_ORDER[idx + 1];
}

/**
 * Soft "almost evolved" tease — progress ≥72% toward the next stage.
 * Returns blurred-next-form meta only (never real art of the locked stage).
 */
function getMascotAlmostEvolvedInfo() {
    if (tamagotchiIsDead) return null;
    const stage = getTamagotchiStageFromLifeMinutes(tamagotchiLifeMinutes);
    if (stage === 'egg') return null;
    const nextStage = getNextMascotLifeStage(stage);
    if (!nextStage) return null;
    // Still on this stage in the current life
    if (getMascotLifeStageIndex(tamagotchiStage) >= getMascotLifeStageIndex(nextStage)) return null;

    const curMin = Number(TAMA_STAGE_MINUTES[stage]) || 0;
    const nextMin = Number(TAMA_STAGE_MINUTES[nextStage]) || 0;
    const span = Math.max(1, nextMin - curMin);
    const progress = Math.max(0, Math.min(1, (Number(tamagotchiLifeMinutes) - curMin) / span));
    if (progress < 0.72) return null;

    const characterType = (tamagotchiCharacterType && tamagotchiCharacterType !== 'none'
        && TAMA_CHARACTER_TYPES.includes(tamagotchiCharacterType))
        ? tamagotchiCharacterType
        : null;

    return {
        currentStage: stage,
        nextStage,
        progress,
        percent: Math.round(progress * 100),
        characterType,
        nextName: getMascotEvolutionDisplayName(characterType, nextStage, { locked: true }),
    };
}

/** Calendar week key for soft vet visit (1× / week). */
function getMascotVetWeekKey() {
    const d = new Date();
    const onejan = new Date(d.getFullYear(), 0, 1);
    const week = Math.ceil((((d - onejan) / 86400000) + onejan.getDay() + 1) / 7);
    return `${d.getFullYear()}-W${week}`;
}

function hasMascotVetVisitThisWeek() {
    return !!tamagotchiLastVetWeek && tamagotchiLastVetWeek === getMascotVetWeekKey();
}

function getMascotVetButtonState() {
    const visited = hasMascotVetVisitThisWeek();
    const sick = !!tamagotchiIsSick;
    const low = tamagotchiHealth < 50;
    return {
        visited,
        urgent: !visited && (sick || low),
        canVisit: !visited,
        label: 'Κτηνίατρος',
        icon: '🩺',
        title: visited
            ? 'Ραντεβού κλειστό για αυτή την εβδομάδα · 1× checkup'
            : careCoinHint(sick ? 'Θεραπεία + checkup' : 'Εβδομαδιαίο checkup · θεραπεία', 'medicine'),
    };
}

/**
 * Soft weekly vet visit — cures sickness + one solid heal. Not spam medicine.
 * @param {object} [opts]
 * @param {boolean} [opts.skipPay] — shop already charged for the kit
 * @returns {{ ok: boolean, reason?: string, pay?: object, wasSick?: boolean }}
 */
function performMascotVetVisit(STORAGE_KEYS, config, opts = {}) {
    if (tamagotchiIsDead) return { ok: false, reason: 'dead' };
    if (tamagotchiStage === 'egg') return { ok: false, reason: 'egg' };
    if (hasMascotVetVisitThisWeek()) return { ok: false, reason: 'already' };

    let pay = { ok: true, paidWith: 'none', cost: 0 };
    if (!opts.skipPay) {
        pay = trySpendMascotCareCoins(STORAGE_KEYS, 'medicine', config);
        if (!pay.ok) return { ok: false, reason: 'coins', pay };
    }

    const wasSick = !!tamagotchiIsSick;
    const before = Number(tamagotchiHealth) || 0;
    tamagotchiIsSick = false;
    tamagotchiSickType = 'none';
    tamagotchiHealth = Math.min(100, before + (wasSick ? 45 : 35));
    if (wasSick) tamagotchiHealth = Math.max(tamagotchiHealth, 90);
    tamagotchiLastVetWeek = getMascotVetWeekKey();

    if (typeof updatePetStats === 'function') {
        updatePetStats(config, STORAGE_KEYS, wasSick ? 10 : 6, 0);
    }
    if (typeof updateSickIndicator === 'function') updateSickIndicator();

    const pool = wasSick ? MASCOT_MESSAGES.vetCured : MASCOT_MESSAGES.vetVisit;
    if (!opts.skipPay) {
        announceMascotCarePayment(pay, pool);
    } else {
        showMascotBubble(
            Array.isArray(pool) ? pool[Math.floor(Math.random() * pool.length)] : pool,
            2200,
        );
    }
    applyMascotCarePreference('medicine', config, STORAGE_KEYS);

    const container = document.getElementById('tm-mascot-container');
    if (container && typeof updateTamagotchiStats === 'function') {
        updateTamagotchiStats(container);
    }
    if (STORAGE_KEYS && typeof saveTamagotchiData === 'function') {
        saveTamagotchiData(STORAGE_KEYS);
    }
    return { ok: true, pay, wasSick };
}

function mascotMsg(key) {
    const pool = MASCOT_MESSAGES[key];
    if (Array.isArray(pool)) return pool[Math.floor(Math.random() * pool.length)];
    return pool || '';
}

function mascotMsgFmt(key, vars = {}) {
    let text = mascotMsg(key);
    Object.keys(vars).forEach(k => {
        text = text.replace(new RegExp(`\\{${k}\\}`, 'g'), String(vars[k]));
    });
    return text;
}

const REPAIR_STATUS_DEFAULT_NAMES = {
    '30': 'εισαγωγές',
    '40': 'προς έλεγχο',
    '65': 'ανταλλακτικά',
    '90': 'προβληματικές'
};

const REPAIR_TIER_LIMITS = {
    '30': { few: 2, some: 4 },
    '40': { few: 2, some: 4 },
    '65': { few: 3, some: 7 },
    '90': { few: 1, some: 2 }
};

function repairCountTier(statusId, count) {
    if (count === 1) return 'one';
    const limits = REPAIR_TIER_LIMITS[statusId] || { few: 2, some: 5 };
    if (count <= limits.few) return 'few';
    if (count <= limits.some) return 'some';
    return 'many';
}

function formatRepairOpinion(template, count, statusName) {
    return template
        .replace(/\{n\}/g, String(count))
        .replace(/\{name\}/g, statusName);
}

function mascotRepairOpinionForStatus(statusId, count, statusName) {
    const tier = repairCountTier(statusId, count);
    const poolKey = `repair${statusId}${tier}`;
    const pool = MASCOT_MESSAGES[poolKey];
    const name = statusName || REPAIR_STATUS_DEFAULT_NAMES[statusId] || `στάδιο ${statusId}`;
    if (!pool?.length) return `${count} στο ${statusId} (${name})`;
    const template = pool[Math.floor(Math.random() * pool.length)];
    return formatRepairOpinion(template, count, name);
}

function parseRepairStatusMenu(root = document) {
    const trackedStatusIds = ['30', '40', '65', '90'];
    const statusIdMap = {};
    let totalRepairs = 0;

    const menuLinks = root.querySelectorAll(
        '.rnr-b-vmenu a[href*="statusid"], .menuLeaf a[href*="statusid"], a[href*="statusid="]'
    );

    menuLinks.forEach(link => {
        const href = link.getAttribute('href') || '';
        const statusIdMatch = href.match(/statusid=(\d+)/);
        if (!statusIdMatch || !trackedStatusIds.includes(statusIdMatch[1])) return;

        const countBadge = link.querySelector('span.badge, .badge');
        if (!countBadge) return;

        const count = parseInt(countBadge.textContent.trim(), 10);
        if (isNaN(count) || count <= 0) return;

        const nameClone = link.cloneNode(true);
        nameClone.querySelector('.statusbadge')?.remove();
        nameClone.querySelectorAll('.badge').forEach(b => b.remove());
        const statusName = nameClone.textContent.replace(/\s+/g, ' ').trim()
            || REPAIR_STATUS_DEFAULT_NAMES[statusIdMatch[1]];

        statusIdMap[statusIdMatch[1]] = { name: statusName, count };
        totalRepairs += count;
    });

    return { statusIdMap, totalRepairs };
}

function mascotRepairUrgencyScore(statusId, count) {
    const tier = repairCountTier(statusId, count);
    const tierWeight = { one: 1, few: 2, some: 4, many: 8 };
    const statusWeight = { '90': 100, '65': 60, '30': 40, '40': 30 };
    return (statusWeight[statusId] || 10) + (tierWeight[tier] || 1) * count;
}

function mascotRepairOpinion(statusIdMap, totalRepairs) {
    return mascotRepairOpinionDetail(statusIdMap, totalRepairs).text;
}

function mascotRepairOpinionDetail(statusIdMap, totalRepairs) {
    if (totalRepairs === 0) {
        return { text: mascotMsg('repairEmpty'), statusId: null, count: 0 };
    }

    const activeIds = ['30', '40', '65', '90'].filter(id => statusIdMap[id]?.count > 0);
    if (activeIds.length === 0) {
        return { text: mascotMsg('repairEmpty'), statusId: null, count: 0 };
    }

    const pickId = activeIds[Math.floor(Math.random() * activeIds.length)];
    const { count, name } = statusIdMap[pickId];
    return {
        text: mascotRepairOpinionForStatus(pickId, count, name),
        statusId: pickId,
        count,
    };
}

function findRepairStatusMenuLink(statusId, root = document) {
    const id = String(statusId || '');
    if (!id) return null;
    const menuLinks = root.querySelectorAll(
        '.rnr-b-vmenu a[href*="statusid"], .menuLeaf a[href*="statusid"], a[href*="statusid="]'
    );
    for (const link of menuLinks) {
        const href = link.getAttribute('href') || '';
        const match = href.match(/statusid=(\d+)/);
        if (match && match[1] === id) return link;
    }
    return null;
}

/** Phoenix: throw a small firebolt from the mascot to a status menu row and briefly "burn" it.
 *  Requires the unlockable «Βολίδα» (firebolt) trick unless options.requireUnlock === false (manual cast).
 */
function isPhoenixFireboltUnlocked() {
    if (typeof isTrickUnlocked === 'function') return isTrickUnlocked('firebolt');
    const unlocked = tamagotchiTaughtTricks?.unlocked;
    return Array.isArray(unlocked) && unlocked.includes('firebolt');
}

function playPhoenixStatusBurn(statusId, options = {}) {
    if (tamagotchiCharacterType !== 'phoenix') return false;
    if (tamagotchiIsDead || tamagotchiStage === 'egg' || tamaCinematicLock) return false;
    const requireUnlock = options.requireUnlock !== false;
    if (requireUnlock && !isPhoenixFireboltUnlocked()) return false;
    const target = options.targetEl || findRepairStatusMenuLink(statusId);
    const mascot = getMascotLiveRoot() || document.getElementById('tm-mascot-container');
    if (!target || !mascot) return false;

    const from = mascot.getBoundingClientRect();
    const to = target.getBoundingClientRect();
    if (!(from.width > 0) || !(to.width > 0)) return false;

    const startX = from.left + from.width * 0.55;
    const startY = from.top + from.height * 0.35;
    const endX = to.left + to.width * 0.55;
    const endY = to.top + to.height * 0.5;
    const dx = endX - startX;
    const dy = endY - startY;
    const dist = Math.hypot(dx, dy);
    const duration = Math.max(420, Math.min(900, dist * 0.85));

    ensurePhoenixBurnStyles();

    const bolt = document.createElement('div');
    bolt.className = 'tm-phoenix-firebolt';
    bolt.setAttribute('aria-hidden', 'true');
    bolt.style.left = `${startX}px`;
    bolt.style.top = `${startY}px`;
    document.body.appendChild(bolt);

    // Face travel direction
    const angle = Math.atan2(dy, dx) * (180 / Math.PI);
    bolt.style.transform = `translate(-50%, -50%) rotate(${angle}deg)`;

    const anim = bolt.animate(
        [
            { transform: `translate(-50%, -50%) rotate(${angle}deg) scale(0.55)`, opacity: 0.2, offset: 0 },
            { transform: `translate(calc(-50% + ${dx * 0.55}px), calc(-50% + ${dy * 0.55}px)) rotate(${angle}deg) scale(1.15)`, opacity: 1, offset: 0.55 },
            { transform: `translate(calc(-50% + ${dx}px), calc(-50% + ${dy}px)) rotate(${angle}deg) scale(0.85)`, opacity: 0.95, offset: 1 },
        ],
        { duration, easing: 'cubic-bezier(0.22, 0.9, 0.3, 1)', fill: 'forwards' }
    );

    const finish = () => {
        try { bolt.remove(); } catch (_) { /* ignore */ }
        target.classList.add('tm-phoenix-status-burn');
        const spark = document.createElement('div');
        spark.className = 'tm-phoenix-status-impact';
        spark.style.left = `${endX}px`;
        spark.style.top = `${endY}px`;
        document.body.appendChild(spark);
        setTimeout(() => {
            try { spark.remove(); } catch (_) { /* ignore */ }
        }, 700);
        setTimeout(() => {
            target.classList.remove('tm-phoenix-status-burn');
        }, 1100);
    };

    anim.finished.then(finish).catch(finish);
    setMascotMood('playful', 5000);
    setMascotState(window.config || {}, 'happy', 1800);
    return true;
}

function ensurePhoenixBurnStyles() {
    if (document.getElementById('tm-phoenix-burn-styles')) return;
    const style = document.createElement('style');
    style.id = 'tm-phoenix-burn-styles';
    style.textContent = `
        .tm-phoenix-firebolt {
            position: fixed;
            z-index: 120050;
            width: 22px;
            height: 22px;
            pointer-events: none;
            border-radius: 50%;
            background:
                radial-gradient(circle at 35% 30%, #fff7ed 0%, #fdba74 28%, #f97316 58%, #ea580c 78%, transparent 82%),
                radial-gradient(circle at 70% 70%, rgba(239, 68, 68, 0.85) 0%, transparent 55%);
            box-shadow:
                0 0 10px 3px rgba(249, 115, 22, 0.75),
                0 0 22px 8px rgba(239, 68, 68, 0.35),
                -8px 0 14px 2px rgba(251, 146, 60, 0.45);
            filter: saturate(1.2);
        }
        .tm-phoenix-firebolt::after {
            content: '';
            position: absolute;
            inset: -6px 10px -6px -14px;
            border-radius: 40%;
            background: linear-gradient(90deg, rgba(251, 146, 60, 0.0), rgba(249, 115, 22, 0.55), rgba(239, 68, 68, 0.15));
            filter: blur(1px);
            transform: translateX(-6px);
        }
        .tm-phoenix-status-impact {
            position: fixed;
            z-index: 120051;
            width: 18px;
            height: 18px;
            margin: 0;
            pointer-events: none;
            border-radius: 50%;
            transform: translate(-50%, -50%);
            background: radial-gradient(circle, #fff7ed 0%, #fb923c 40%, transparent 70%);
            box-shadow: 0 0 18px 8px rgba(249, 115, 22, 0.55);
            animation: tm-phoenix-impact 0.65s ease-out forwards;
        }
        @keyframes tm-phoenix-impact {
            0% { transform: translate(-50%, -50%) scale(0.4); opacity: 1; }
            70% { transform: translate(-50%, -50%) scale(2.2); opacity: 0.85; }
            100% { transform: translate(-50%, -50%) scale(2.8); opacity: 0; }
        }
        .tm-phoenix-status-burn {
            position: relative !important;
            animation: tm-phoenix-scorch 1.05s ease-out;
            box-shadow: 0 0 0 2px rgba(249, 115, 22, 0.55), 0 0 18px rgba(239, 68, 68, 0.35) !important;
            border-radius: 6px;
        }
        .tm-phoenix-status-burn::after {
            content: '';
            position: absolute;
            inset: 0;
            border-radius: inherit;
            pointer-events: none;
            background: linear-gradient(110deg, transparent 20%, rgba(255, 237, 213, 0.35) 45%, rgba(249, 115, 22, 0.28) 55%, transparent 80%);
            animation: tm-phoenix-heat-sweep 0.9s ease-out;
        }
        @keyframes tm-phoenix-scorch {
            0% { filter: brightness(1); }
            25% { filter: brightness(1.25) saturate(1.35); }
            100% { filter: brightness(1); }
        }
        @keyframes tm-phoenix-heat-sweep {
            0% { opacity: 0; transform: translateX(-30%); }
            35% { opacity: 1; }
            100% { opacity: 0; transform: translateX(35%); }
        }
    `;
    document.head.appendChild(style);
}

// ─── Phoenix mythical FX: solar sovereign presence (lighter than Aether) ───
let phoenixMythFxActive = false;
let phoenixMythFxTimer = null;
let phoenixLastStageCinematic = '';
let phoenixLastFootprintAt = 0;

function stopPhoenixMythicFx() {
    phoenixMythFxActive = false;
    if (phoenixMythFxTimer) {
        clearTimeout(phoenixMythFxTimer);
        phoenixMythFxTimer = null;
    }
    const container = document.getElementById('tm-mascot-container');
    if (!container) return;
    container.classList.remove('tm-phoenix-sovereign', 'tm-phoenix-glow-on', 'tm-phoenix-ring-on', 'tm-phoenix-react');
    container.querySelectorAll('.tm-phoenix-mythic-footprint, .tm-phoenix-stage-ember').forEach((el) => el.remove());
    document.getElementById('tm-phoenix-stage-flash')?.remove();
}

function rollPhoenixAuraLayers(container, stage) {
    if (!container || !phoenixMythFxActive) return;
    const tier = PHOENIX_STAGE_TIER[stage] || 1;
    const parked = container.classList.contains('mascot-parked') || !!mascotPositionLocked;
    container.classList.toggle('tm-phoenix-glow-on', parked && tier >= 3
        ? true
        : Math.random() < (0.1 + tier * 0.09));
    container.classList.toggle('tm-phoenix-ring-on', tier >= 3 && (parked || Math.random() < (0.06 + (tier - 2) * 0.07)));
}

function schedulePhoenixAuraRoll(container, stage) {
    if (!phoenixMythFxActive) return;
    phoenixMythFxTimer = setTimeout(() => {
        if (!phoenixMythFxActive) return;
        rollPhoenixAuraLayers(container, stage);
        schedulePhoenixAuraRoll(container, stage);
    }, 9000 + Math.random() * 14000);
}

function syncPhoenixMythicFx(stage = typeof tamagotchiStage !== 'undefined' ? tamagotchiStage : 'evo1') {
    stopPhoenixMythicFx();
    if (tamagotchiIsDead || stage === 'egg') return;
    if (tamagotchiCharacterType !== 'phoenix') return;
    const container = document.getElementById('tm-mascot-container');
    if (!container || !container.classList.contains('mascot-char-phoenix')) return;
    phoenixMythFxActive = true;
    container.classList.add('tm-phoenix-sovereign');
    rollPhoenixAuraLayers(container, stage);
    phoenixMythFxTimer = setTimeout(() => {
        if (!phoenixMythFxActive) return;
        rollPhoenixAuraLayers(container, stage);
        schedulePhoenixAuraRoll(container, stage);
    }, 500 + Math.random() * 900);
}

function playPhoenixMythicFootprint(container) {
    if (!container || tamagotchiCharacterType !== 'phoenix') return;
    const now = Date.now();
    if (now - phoenixLastFootprintAt < 4000) return;
    phoenixLastFootprintAt = now;
    container.querySelectorAll('.tm-phoenix-mythic-footprint').forEach((el) => el.remove());
    const mark = document.createElement('div');
    mark.className = 'tm-phoenix-mythic-footprint';
    container.appendChild(mark);
    setTimeout(() => mark.remove(), 3200);
}

/** Lightweight EVOLUTION flash for non-mythic characters (dragon, robot, …). */
function playGenericStageCinematic(stage, { hatch = false } = {}) {
    if (!stage || stage === 'egg') return;
    if (tamagotchiCharacterType === 'aether' || tamagotchiCharacterType === 'phoenix') return;

    const stageGr = (typeof MASCOT_STAGE_GR !== 'undefined' && MASCOT_STAGE_GR[stage])
        ? MASCOT_STAGE_GR[stage]
        : stage;
    const charMeta = MASCOT_CHARACTERS?.[tamagotchiCharacterType];
    const name = charMeta?.nameGr || charMeta?.name || tamagotchiCharacterType || 'Mascot';
    const emoji = charMeta?.emoji || '✨';

    document.getElementById('tm-evo-stage-flash')?.remove();
    const overlay = document.createElement('div');
    overlay.id = 'tm-evo-stage-flash';
    overlay.className = 'tm-evo-stage-flash';
    overlay.innerHTML = `
        <div class="tm-evo-stage-flash-veil"></div>
        <div class="tm-evo-stage-flash-card">
            <div class="tm-evo-stage-flash-kicker">${hatch ? 'HATCH' : 'EVOLUTION'}</div>
            <div class="tm-evo-stage-flash-emoji">${emoji}</div>
            <div class="tm-evo-stage-flash-title">${stageGr}</div>
            <div class="tm-evo-stage-flash-sub">${name}</div>
        </div>
    `;
    document.body.appendChild(overlay);

    const container = getMascotLiveRoot() || document.getElementById('tm-mascot-container');
    if (container) {
        container.classList.add('tm-evo-react');
        setTimeout(() => container.classList.remove('tm-evo-react'), 1600);
    }
    setTimeout(() => overlay.remove(), 2800);
}

function playPhoenixStageCinematic(stage, { hatch = false } = {}) {
    if (tamagotchiCharacterType !== 'phoenix') return;
    const title = PHOENIX_STAGE_TITLES[stage] || stage;
    const key = `${hatch ? 'hatch' : 'evo'}:${stage}`;
    if (phoenixLastStageCinematic === key && !hatch) return;
    phoenixLastStageCinematic = key;

    const stageIdx = PHOENIX_STAGE_ORDER.indexOf(stage);
    const prevStage = stageIdx > 0 ? PHOENIX_STAGE_ORDER[stageIdx - 1] : null;
    document.getElementById('tm-phoenix-stage-flash')?.remove();

    const overlay = document.createElement('div');
    overlay.id = 'tm-phoenix-stage-flash';
    overlay.className = 'tm-phoenix-stage-flash is-epic';
    overlay.innerHTML = `
        <div class="tm-phoenix-stage-flash-veil"></div>
        <div class="tm-phoenix-stage-flash-burst"></div>
        <div class="tm-phoenix-stage-flash-cutin" id="tm-phoenix-cutin-host"></div>
        <div class="tm-phoenix-stage-flash-card">
            <div class="tm-phoenix-stage-flash-kicker">${hatch ? 'MYTHICAL HATCH' : 'EVOLUTION'}</div>
            <div class="tm-phoenix-stage-flash-title">${title}</div>
            <div class="tm-phoenix-stage-flash-sub">Ashborn Phoenix</div>
        </div>
        <div class="tm-phoenix-stage-flash-timeline">
            ${prevStage ? `<div class="tm-phoenix-timeline-sil is-prev" title="${PHOENIX_STAGE_TITLES[prevStage]}"></div>` : ''}
            <div class="tm-phoenix-timeline-sil is-next" title="${title}"></div>
        </div>
    `;
    document.body.appendChild(overlay);

    try {
        const host = overlay.querySelector('#tm-phoenix-cutin-host');
        const liveSvg = document.querySelector('#tm-mascot-container .tm-mascot-robot.mascot-char-phoenix');
        if (host && liveSvg) {
            const clone = liveSvg.cloneNode(true);
            clone.removeAttribute('id');
            clone.style.cssText = 'width:100%;height:100%;';
            host.appendChild(clone);
        }
    } catch (_) { /* ignore */ }

    const container = document.getElementById('tm-mascot-container');
    if (container) {
        for (let i = 0; i < 6; i++) {
            const ember = document.createElement('div');
            ember.className = 'tm-phoenix-stage-ember';
            ember.style.left = `${42 + Math.random() * 16}%`;
            ember.style.top = `${38 + Math.random() * 18}%`;
            ember.style.animationDelay = `${(i * 0.08).toFixed(2)}s`;
            container.appendChild(ember);
            setTimeout(() => ember.remove(), 1600);
        }
        container.classList.add('tm-phoenix-react');
        setTimeout(() => container.classList.remove('tm-phoenix-react'), 1800);
    }
    setTimeout(() => overlay.remove(), 3000);
}

// ─── Storm Leviathan FX — real atmospheric phenomena (sparse random, NOT always-on) ───
let leviathanPresenceTimer = null;
let leviathanEventTimer = null;
let leviathanFxActive = false;

const LEVIATHAN_EPIC_EVENTS = [
    'godshadow',       // anvil cloud + crepuscular rays
    'split_sky',       // branched cloud-to-ground lightning
    'eye_of_storm',    // cyclone eyewall
    'apocalypse_glance', // distant sheet-lightning sky flash
    'ascension_drift', // convective updraft
    'depth_call',      // bioluminescent upwelling + caustics
];

/** Local aura phenomena around the mascot (presence bursts). */
const LEVIATHAN_AURA_KINDS = [
    'corona',      // St. Elmo's fire / corona discharge
    'pressure',    // sudden barometric drop haze
    'squall',      // gust-front rain sheet
    'sheet_flash', // distant sheet lightning flicker
];

function isLeviathanTempestUnlocked() {
    if (typeof isTrickUnlocked === 'function') return isTrickUnlocked('tempest');
    const unlocked = tamagotchiTaughtTricks?.unlocked;
    return Array.isArray(unlocked) && unlocked.includes('tempest');
}

function leviRand(a, b) {
    return a + Math.random() * (b - a);
}

function leviFxMount(el, ttlMs) {
    el.classList.add('tm-levi-fx');
    el.setAttribute('aria-hidden', 'true');
    document.body.appendChild(el);
    setTimeout(() => el.remove(), ttlMs);
    return el;
}

