function getGamificationSettingsHTML(STORAGE_KEYS) {
    return getLevelUpSettingsHTML() + getMascotSettingsHTML();
}

function initGamificationSettings(config, STORAGE_KEYS) {
    // Populate Checkboxes
    const populateCheckbox = (id, key) => {
        const checkbox = document.getElementById(id);
        if (checkbox) checkbox.checked = config[key];
    };
    populateCheckbox('tm-setting-levelup-enabled', 'levelUpSystemEnabled');
    populateCheckbox('tm-setting-daily-bounties-enabled', 'dailyBountiesEnabled');
    populateCheckbox('tm-setting-confetti-enabled', 'confettiEnabled');
    populateCheckbox('tm-setting-achievements-enabled', 'achievementsEnabled');
    populateCheckbox('tm-setting-mascot-enabled', 'interactiveMascotEnabled');

    // Populate new feature checkboxes
    populateCheckbox('tm-setting-random-events-enabled', 'randomEventsEnabled');
    populateCheckbox('tm-setting-personal-dashboard-enabled', 'personalDashboardEnabled');
    populateCheckbox('tm-setting-shop-enabled', 'shopEnabled');
    populateCheckbox('tm-setting-eod-checklist-enabled', 'eodChecklistEnabled');

    document.getElementById('tm-setting-mascot-speed').value = config.mascotRoamingSpeed;

    // Add event listener to shop checkbox to update UI immediately
    const shopCheckbox = document.getElementById('tm-setting-shop-enabled');
    if (shopCheckbox) {
        shopCheckbox.addEventListener('change', () => {
            // Save immediately
            const value = shopCheckbox.checked;
            GM_setValue('shopEnabled', value);
            config.shopEnabled = value;
            
            // Update shop button visibility
            updateGamificationLayerVisibility(config);
        });
    }

    const levelUpCheckbox = document.getElementById('tm-setting-levelup-enabled');
    if (levelUpCheckbox) {
        levelUpCheckbox.addEventListener('change', () => {
            config.levelUpSystemEnabled = levelUpCheckbox.checked;
            GM_setValue('levelUpSystemEnabled', levelUpCheckbox.checked);
            updateGamificationLayerVisibility(config);
        });
    }

    const dailyBountiesCheckbox = document.getElementById('tm-setting-daily-bounties-enabled');
    if (dailyBountiesCheckbox) {
        dailyBountiesCheckbox.addEventListener('change', () => {
            config.dailyBountiesEnabled = dailyBountiesCheckbox.checked;
            GM_setValue('dailyBountiesEnabled', dailyBountiesCheckbox.checked);
            updateGamificationLayerVisibility(config);
        });
    }

    const mascotCheckbox = document.getElementById('tm-setting-mascot-enabled');
    if (mascotCheckbox) {
        mascotCheckbox.addEventListener('change', () => {
            config.interactiveMascotEnabled = mascotCheckbox.checked;
            GM_setValue('interactiveMascotEnabled', mascotCheckbox.checked);
            updateGamificationLayerVisibility(config);
        });
    }

    document.getElementById('tm-setting-professional-mode-btn')?.addEventListener('click', () => {
        applyGamificationPreset('professional', config, STORAGE_KEYS);
    });
    document.getElementById('tm-setting-gamification-mode-btn')?.addEventListener('click', () => {
        applyGamificationPreset('gamification', config, STORAGE_KEYS);
    });

    updateGamificationLayerVisibility(config);

    // Talent unlock now handled in dedicated modal (showTalentsModal)
}

// Function to update shop button visibility based on config
function updateShopButtonVisibility(config) {
    // Shop visibility depends ONLY on shopEnabled, not mascot
    const shopOn = !!config.shopEnabled;

    // Update shop tab in dashboard if it exists
    const shopTab = document.querySelector('.tm-dashboard-tab[data-tab="shop"]');
    if (shopTab) {
        shopTab.style.display = shopOn ? '' : 'none';
    }
    
    // Update coin balance clickability in dashboard
    const coinBalance = document.getElementById('tm-dashboard-coin-balance');
    if (coinBalance) {
        if (shopOn) {
            coinBalance.style.cursor = 'pointer';
            coinBalance.title = 'Click to open Shop';
        } else {
            coinBalance.style.cursor = 'default';
            coinBalance.title = '';
        }
    }
    
    // Update coin balance in XP bar widget
    const coinBalanceWidget = document.getElementById('tm-coin-balance');
    if (coinBalanceWidget) {
        if (shopOn) {
            coinBalanceWidget.style.display = '';
            coinBalanceWidget.style.cursor = 'pointer';
            coinBalanceWidget.title = 'Click to open Shop';
        } else {
            coinBalanceWidget.style.display = 'none';
        }
    }
}

const GAMIFICATION_PRESET_KEYS = [
    'levelUpSystemEnabled',
    'dailyBountiesEnabled',
    'shopEnabled',
    'interactiveMascotEnabled',
    'achievementsEnabled',
    'confettiEnabled',
    'randomEventsEnabled',
    'notificationsEnabled',
];

const GAMIFICATION_PRESET_CHECKBOX_IDS = {
    levelUpSystemEnabled: 'tm-setting-levelup-enabled',
    dailyBountiesEnabled: 'tm-setting-daily-bounties-enabled',
    shopEnabled: 'tm-setting-shop-enabled',
    interactiveMascotEnabled: 'tm-setting-mascot-enabled',
    achievementsEnabled: 'tm-setting-achievements-enabled',
    confettiEnabled: 'tm-setting-confetti-enabled',
    randomEventsEnabled: 'tm-setting-random-events-enabled',
    notificationsEnabled: 'tm-setting-notifications-enabled',
};

function updateGamificationLayerVisibility(config) {
    updateShopButtonVisibility(config);

    if (typeof window.updateNotificationUIVisibility === 'function') {
        window.updateNotificationUIVisibility(config);
    }

    const xpBar = document.getElementById('tm-xp-bar-container');
    if (xpBar) {
        xpBar.style.display = config.levelUpSystemEnabled !== false ? '' : 'none';
    }

    const mascot = document.getElementById('tm-mascot-container');
    if (mascot) {
        mascot.style.display = config.interactiveMascotEnabled !== false ? '' : 'none';
    }

    const questsBtn = document.getElementById('tm-quests-btn');
    if (questsBtn) {
        questsBtn.style.display = isDailyBountiesEnabled(config) ? '' : 'none';
    }
}

function applyGamificationPreset(preset, config, STORAGE_KEYS) {
    const values = preset === 'professional'
        ? {
            levelUpSystemEnabled: false,
            dailyBountiesEnabled: false,
            shopEnabled: false,
            interactiveMascotEnabled: false,
            achievementsEnabled: false,
            confettiEnabled: false,
            randomEventsEnabled: false,
            notificationsEnabled: false,
        }
        : {
            levelUpSystemEnabled: true,
            dailyBountiesEnabled: true,
            shopEnabled: true,
            interactiveMascotEnabled: true,
            achievementsEnabled: true,
            confettiEnabled: true,
            randomEventsEnabled: true,
            notificationsEnabled: true,
        };

    GAMIFICATION_PRESET_KEYS.forEach((key) => {
        GM_setValue(key, values[key]);
        config[key] = values[key];
    });

    Object.entries(GAMIFICATION_PRESET_CHECKBOX_IDS).forEach(([key, id]) => {
        const el = document.getElementById(id);
        if (el) el.checked = values[key];
    });

    updateGamificationLayerVisibility(config);

    if (typeof window.showPositiveMessage === 'function') {
        window.showPositiveMessage(
            preset === 'professional'
                ? 'Professional mode — work tools only. Reload για πλήρη απόκρυψη mascot.'
                : 'Gamification mode ενεργοποιήθηκε.'
        );
    }
}

function saveGamificationSettings() {
    const saveCheckbox = (id, key) => {
        const checkbox = document.getElementById(id);
        if (checkbox) {
            const value = checkbox.checked;
            GM_setValue(key, value);
            config[key] = value;
        }
    };

    const saveNumber = (id, key) => {
        const input = document.getElementById(id);
        if (input) {
            const value = parseInt(input.value, 10);
            if (!isNaN(value) && value >= (input.min || 0)) {
                GM_setValue(key, value);
                config[key] = value;
            }
        }
    };

    // --- Save Gamification/Fun Settings ---
    saveCheckbox('tm-setting-levelup-enabled', 'levelUpSystemEnabled');
    saveCheckbox('tm-setting-daily-bounties-enabled', 'dailyBountiesEnabled');
    saveCheckbox('tm-setting-mascot-enabled', 'interactiveMascotEnabled');
    saveCheckbox('tm-setting-confetti-enabled', 'confettiEnabled');
    saveCheckbox('tm-setting-random-events-enabled', 'randomEventsEnabled');
    saveCheckbox('tm-setting-personal-dashboard-enabled', 'personalDashboardEnabled');
    saveCheckbox('tm-setting-shop-enabled', 'shopEnabled');
    saveCheckbox('tm-setting-eod-checklist-enabled', 'eodChecklistEnabled');
    saveNumber('tm-setting-mascot-speed', 'mascotRoamingSpeed');

    // Update shop button visibility after saving
    if (typeof updateGamificationLayerVisibility === 'function') {
        updateGamificationLayerVisibility(config);
    }

    // Apply EOD checklist visibility immediately
    const eodBtn = document.getElementById('tm-eod-btn');
    if (config.eodChecklistEnabled === false) {
        eodBtn?.remove();
    } else if (!eodBtn && typeof window.initEODChecklist === 'function') {
        window.initEODChecklist(config, STORAGE_KEYS);
    }

    // Weather location is now hardcoded to Athens
}

